import numpy as np
# MECHANISM: Reward exact fits and penalize close misses, favoring larger bins slightly.

def priority(item, bins):
    return np.maximum(bins - item, 0) * (1 + (bins - item) / 150)

import numpy as np
# MECHANISM: Prefer bins with exact fits and penalize bins with very small remaining capacity

def priority(item, bins):
    return bins / (bins + item)

import numpy as np

# MECHANISM: Prioritize bins based on a combination of remaining capacity and fit quality, penalize very small remaining capacity

def priority(item, bins):
    return (bins - item) / (bins + item) * (bins / 150)
